#!/usr/bin/env bash
# RemoteOS MCP - enroll this Linux box with dev1 (#101): the ONE fixed line of the README.
# Usage: curl -fsSL https://raw.githubusercontent.com/zbynekdrlik/remoteos-mcp/main/enroll-linux.sh | sudo bash
# Generated by scripts/build_installers.py from installers/enroll-sh/: edit the parts, not this file.
set -euo pipefail
INSTALLER_NAME="install-linux.sh"
ENROLL_OS="linux"

# The values are public constants (installers/enroll-values.conf), never a secret: the endpoint only
# queues the registration, and dev1's operator accepts it (remoteos-gateway enroll-accept).
ENROLL_URL="https://enroll-dev1.newlevel.media/enroll/"
ENROLL_SSH_KEY="ssh-ed25519 AAAAC3NzaC1lZDI1NTE5AAAAIB/akQWI95uekn0/CRfQA2I8vu1a/kU9sx6SmUdA3lOf"
RAW="https://raw.githubusercontent.com/zbynekdrlik/remoteos-mcp"
LOG_TAIL_BYTES=200000

# The installer's source: REMOTEOS_MCP_REF (default main), a plain branch, tag or commit name.
ref_ok() {
    [[ "${1-}" =~ ^[A-Za-z0-9][A-Za-z0-9._/-]*$ ]] && [[ ${#1} -le 100 ]] && [[ "$1" != *..* ]]
}

# The short hostname, for the log's header: letters, digits and . _ - only, else "unknown".
host_name() {
    local name
    name=$(hostname 2>/dev/null || uname -n)
    name=${name%%.*}
    [[ "$name" =~ ^[A-Za-z0-9._-]+$ ]] && [[ ${#name} -le 64 ]] || name="unknown"
    printf '%s' "$name"
}

# The tail of the install log to dev1 (POST <endpoint>log), so a failure is readable there with no
# one typing anything here. Best effort: a failed post is said, never fatal.
post_log() {
    local code=$1 log=$2
    if tail -c "$LOG_TAIL_BYTES" "$log" | curl -q -fsS --proto =https --max-time 30 -A remoteos-enroll \
        -H "Content-Type: text/plain; charset=utf-8" -H "X-Remoteos-Host: $(host_name)" \
        -H "X-Remoteos-Os: $ENROLL_OS" -H "X-Remoteos-Exit: $code" --data-binary @- "${ENROLL_URL}log" >/dev/null; then
        echo "  The install log went to dev1."
    else
        echo "  [!] The install log could not be sent to dev1."
    fi
}

main() {
    local ref=${REMOTEOS_MCP_REF:-main} work code
    echo ""
    echo "  RemoteOS MCP - enrolling this box with dev1"
    echo ""
    if ! ref_ok "$ref"; then
        echo "  [X] REMOTEOS_MCP_REF is not a plain branch, tag or commit name -- nothing was changed on this box"
        exit 1
    fi
    work=$(mktemp -d)
    # shellcheck disable=SC2064 # the folder is fixed now
    trap "rm -rf '$work'" EXIT
    : >"$work/log"
    if ! curl -q -fsSL --proto =https --max-time 120 -o "$work/install" "$RAW/$ref/$INSTALLER_NAME" 2>>"$work/log"; then
        echo "  [X] Could not download $INSTALLER_NAME ($ref) -- nothing was changed on this box" | tee -a "$work/log"
        post_log 1 "$work/log"
        exit 1
    fi
    set +e
    REMOTEOS_ENROLL="$ENROLL_URL" REMOTEOS_ENROLL_SSH_KEY="$ENROLL_SSH_KEY" REMOTEOS_MCP_REF="$ref" \
        bash "$work/install" </dev/null 2>&1 | tee -a "$work/log"
    code=${PIPESTATUS[0]}
    set -e
    if [[ "$code" -ne 0 ]]; then
        echo "  [X] The install failed (exit $code)."
        post_log "$code" "$work/log"
        exit "$code"
    fi
    echo ""
    echo "  Done: dev1 has this box's registration. It is enrolled once dev1 accepts it."
}

main "$@"
